<script>
// Complete data dictionary for Mouse Feeders
const tabData = {
  "M-FEED": {
    preTitle: "STANDARD",
    title: "M-FEED",
    description: "Mouse food tray. A plastic feeder with a metal insert.",
    imageSrc: "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/M-FEED.png", // Use the main one from the third image
    advantages: [
      "Designed for use with Innocage® Mouse bottom.",
      "Body: PS plastic",
      "Grate: zinc-plated steel.",
      "Recyclable after the metal grate is removed."
    ]
  },
  "M-FEED-P": {
    preTitle: "PLASTIC",
    title: "M-FEED P",
    description: "Mouse food tray. Standard feeder.",
    imageSrc: "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/M-FEED-P-1.png",
    advantages: [
      "Plastic feeder.",
      "Designed for use with Innocage® Mouse bottom.",
      "100% PET plastic. BPA-Free."
    ]
  },
  "M-FEED-SS": {
    preTitle: "STAINLESS STEEL",
    title: "M-FEED-SS",
    description: "Mouse food tray. A plastic feeder with stainless steel insert.",
    imageSrc: "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/M-FEED-SS.png",
    advantages: [
      "Designed for use with Innocage® Mouse bottom.",
      "Body: PET plastic.",
      "Grate: stainless steel.",
      "Recyclable after the stainless steel grate is removed."
    ]
  }
};

const tabs = document.querySelectorAll('.tab');
const dynamicContentArea = document.getElementById('dynamic-content-area');
const advantagesArea = document.getElementById('advantages-area');

const preTitleEl = document.getElementById('dynamic-pre-title');
const titleEl = document.getElementById('dynamic-title');
const descriptionEl = document.getElementById('dynamic-description');
const advantagesListEl = document.getElementById('dynamic-advantages');
const imageEl = document.getElementById('dynamic-image');

// Function to update the page content based on tabId
function updateContent(tabId) {
  const data = tabData[tabId];
  if (!data) return;

  // Fade out
  dynamicContentArea.style.opacity = 0;
  advantagesArea.style.opacity = 0;
  imageEl.style.opacity = 0;

  setTimeout(() => {
    // Update Texts
    preTitleEl.textContent = data.preTitle;
    titleEl.textContent = data.title;
    descriptionEl.textContent = data.description;

    // Update Advantages List
    advantagesListEl.innerHTML = '';
    data.advantages.forEach(adv => {
      const li = document.createElement('li');
      li.textContent = adv;
      advantagesListEl.appendChild(li);
    });

    // Fade in text
    dynamicContentArea.style.opacity = 1;
    advantagesArea.style.opacity = 1;

    // Update image
    imageEl.src = data.imageSrc;
    imageEl.onload = () => { imageEl.style.opacity = 1; };
    imageEl.onerror = () => {
      imageEl.style.opacity = 1;
    };
  }, 250);
}

// Add click event listeners to tabs
tabs.forEach(tab => {
  tab.addEventListener('click', () => {
    if (tab.classList.contains('active')) return;

    // Update active class
    tabs.forEach(t => t.classList.remove('active'));
    tab.classList.add('active');

    // Update content
    const tabId = tab.getAttribute('data-id');
    updateContent(tabId);
  });
});

// Initialize with the first tab
updateContent('M-FEED');
</script>


